using System;using System.Drawing;using System.IO;using System.Reflection;using System.Windows.Forms;
class ChromeScrollTests{
 [STAThread]static void Main(){ProfileStore.FileName=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString(),"profiles.json");var flags=BindingFlags.Instance|BindingFlags.NonPublic;using(var f=new ThebestRGB()){f.Show();f.ClientSize=new Size(880,600);Application.DoEvents();var main=(Panel)typeof(ThebestRGB).GetField("main",flags).GetValue(f);var chrome=(Panel)typeof(ThebestRGB).GetField("windowChrome",flags).GetValue(f);var before=chrome.Bounds;main.AutoScrollPosition=new Point(0,500);Application.DoEvents();if(main.AutoScrollPosition.Y==0)throw new Exception("Did not scroll");if(chrome.Parent!=f||chrome.Bounds!=before||!chrome.Visible)throw new Exception("Chrome moved on scroll");foreach(string name in new[]{"windowMinimize","windowMaximize","windowClose"}){var b=(Button)typeof(ThebestRGB).GetField(name,flags).GetValue(f);if(!b.Visible||!chrome.ClientRectangle.Contains(b.Bounds))throw new Exception("Button not visible: "+name);}typeof(ThebestRGB).GetField("exitRequested",flags).SetValue(f,true);f.Close();}Console.WriteLine("PASS: window controls remain fixed and visible after scrolling.");}
}
